<?php
require dirname(__DIR__,2).'/vendor/autoload.php';$app=require dirname(__DIR__,2).'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
$marker='ui-student-welcome-'.time();$password=bin2hex(random_bytes(16));$admin=App\Models\User::where('role','admin')->firstOrFail();$students=[];
Illuminate\Support\Facades\DB::transaction(function()use($marker,$password,$admin,&$students){foreach(['toeic','vstep','course'] as $track){$user=App\Models\User::create(['name'=>'Thí sinh kiểm tra giao diện','email'=>$marker.'-'.$track.'@example.test','password'=>$password,'role'=>'student','is_active'=>true,'exam_track'=>$track,'login_scope'=>$track]);$students[$track]=['id'=>$user->id,'email'=>$user->email];$exam=App\Models\Exam::create(['title'=>'Bài thi '.strtoupper($track).' · Kiểm tra giao diện','description'=>'Kiểm tra ngày thi và số lượt trước khi bắt đầu.','duration_minutes'=>60,'status'=>'published','created_by'=>$admin->id,'exam_track'=>$track]);$question=App\Models\Question::create(['content'=>$marker.'-'.$track,'part'=>5,'options'=>['A'=>'Answer A','B'=>'Answer B'],'correct_option'=>'A','kind'=>'mcq','skill'=>$track==='vstep'?'reading':null,'created_by'=>$admin->id,'exam_track'=>$track]);$exam->questions()->attach($question->id,['position'=>1]);$access=App\Models\ExamAccess::create(['user_id'=>$user->id,'exam_id'=>$exam->id,'exam_date'=>now('Asia/Bangkok')->toDateString(),'max_attempts'=>2,'is_active'=>true,'access_mode'=>'day','created_by'=>$admin->id]);$students[$track]+=['exam_id'=>$exam->id,'question_id'=>$question->id,'access_id'=>$access->id];}});
file_put_contents(__DIR__.'/student-welcome-data.json',json_encode(['marker'=>$marker,'password'=>$password,'students'=>$students]));echo "Student UI test fixtures created.\n";
